/* LeetCode 125: Valid Palindrome. Ignore non-alphanumeric and case. O(n) time, O(1) space. https://leetcode.com/problems/valid-palindrome/ */
public class ValidPalindrome{static boolean isPalindrome(String s){int l=0,r=s.length()-1;while(l<r){while(l<r&&!Character.isLetterOrDigit(s.charAt(l)))l++;while(l<r&&!Character.isLetterOrDigit(s.charAt(r)))r--;if(Character.toLowerCase(s.charAt(l++))!=Character.toLowerCase(s.charAt(r--)))return false;}return true;}public static void main(String[]x){System.out.println(isPalindrome("A man, a plan, a canal: Panama"));}}